-- IP Gate receives evidence ownership from D8 technical and D12 product/design without making legal claims.
create table if not exists public.autonomous_ip_evidence_links(id uuid primary key default gen_random_uuid(),innovation_id uuid not null references public.ip_innovations(id) on delete cascade,department_id integer not null check(department_id in(8,12,14)),evidence_type text not null,reference text not null,evidence_hash text not null,legal_claim boolean not null default false check(legal_claim=false),created_by uuid,created_at timestamptz not null default now());
alter table public.autonomous_ip_evidence_links enable row level security;do $$begin create policy ip_links_superadmin_read on public.autonomous_ip_evidence_links for select to authenticated using(private.is_superadmin());exception when duplicate_object then null;end$$;grant select on public.autonomous_ip_evidence_links to authenticated;
create or replace function public.superadmin_link_ip_evidence(p_innovation_id uuid,p_department_id integer,p_evidence_type text,p_reference text,p_evidence_hash text)
returns public.autonomous_ip_evidence_links language plpgsql security definer set search_path=public,private,auth as $$declare r public.autonomous_ip_evidence_links%rowtype;begin if auth.uid() is null or not private.is_superadmin()then raise exception 'SUPERADMIN_REQUIRED' using errcode='42501';end if;if p_department_id not in(8,12,14)then raise exception 'IP_EVIDENCE_DEPARTMENT_REQUIRED';end if;insert into public.autonomous_ip_evidence_links(innovation_id,department_id,evidence_type,reference,evidence_hash,created_by)values(p_innovation_id,p_department_id,btrim(p_evidence_type),btrim(p_reference),btrim(p_evidence_hash),auth.uid())returning * into r;return r;end$$;
revoke all on function public.superadmin_link_ip_evidence(uuid,integer,text,text,text) from public;grant execute on function public.superadmin_link_ip_evidence(uuid,integer,text,text,text) to authenticated;